const patch = "*** Begin Patch
*** Update File: /Users/burakemre/Code/lobu/.claude/worktrees/social-interest-event-thread/packages/owletto/src/lib/activity-links.ts
@@
 export function parseAppHref(href: string): {
@@
 }
+
+export type ActivityHref =
+	| {
+			kind: "app";
+			pathname: string;
+			search: Record<string, string> | undefined;
+	  }
+	| { kind: "external"; href: string }
+	| { kind: "invalid" };
+
+/**
+ * Keep app-relative activity targets in TanStack Router, but leave absolute
+ * HTTP(S) destinations intact for a normal browser navigation. Feeding an
+ * absolute URL to TanStack's `to` prop resolves it relative to the current
+ * route (`.../chat/https:/app.lobu.ai/...`) and lands on the 404 page.
+ */
+export function classifyActivityHref(href: string): ActivityHref {
+	const trimmed = href.trim();
+	if (!trimmed) return { kind: "invalid" };
+
+	try {
+		const absolute = new URL(trimmed);
+		if (absolute.protocol !== "http:" && absolute.protocol !== "https:") {
+			return { kind: "invalid" };
+		}
+		return { kind: "external", href: absolute.href };
+	} catch {
+		// App links are root-relative. Reject protocol-relative URLs instead of
+		// handing `//host/path` to the client router as a workspace path.
+		if (!trimmed.startsWith("/") || trimmed.startsWith("//")) {
+			return { kind: "invalid" };
+		}
